import os
import json
from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential

def extract_receipt_data(receipt_image_path):
    endpoint = os.getenv("AZURE_FORM_RECOGNIZER_ENDPOINT")
    key = os.getenv("AZURE_FORM_RECOGNIZER_KEY")
    model_id = "prebuilt-receipt"

    document_analysis_client = DocumentAnalysisClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    with open(receipt_image_path, "rb") as f:
        poller = document_analysis_client.begin_analyze_document(model_id, document=f)

    receipt = poller.result()

    merchant = None
    tax = None
    total = None
    items = []

    if receipt.documents:
        for name, field in receipt.documents[0].fields.items():
            if name == "MerchantName" and field.value:
                merchant = field.value
            elif name == "TotalTax" and field.value:
                tax = float(field.value)
            elif name == "Total" and field.value:
                total = float(field.value)
            elif name == "Items" and field.value:
                for item in field.value:
                    item_data = {
                        "name": item.value.get("Name", {}).value if item.value.get("Name") else None,
                        "quantity": float(item.value.get("Quantity", {}).value) if item.value.get("Quantity") else None,
                        "price": float(item.value.get("TotalPrice", {}).value) if item.value.get("TotalPrice") else None,
                        "unit_price": float(item.value.get("Price", {}).value) if item.value.get("Price") else None
                    }
                    items.append(item_data)

    return {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items
    }
